interface User {
  id: string;
  email: string;
  name: string;
  role: 'user' | 'admin';
}

type UserUpdate = Partial<Omit<User, 'id'>>;

async function patchUser(id: string, patch: UserUpdate): Promise<User> {
  return fetch(`/api/users/${id}`, { method: 'PATCH', body: JSON.stringify(patch) }).then(r => r.json());
}

patchUser('1', { name: 'Ada' }); // OK — only name

type UserPublic = Pick<User, 'id' | 'name' | 'email'>;
type UserSafe = Omit<User, 'role'>;

type CreateUser = Omit<User, 'id'>;

type UserWithRequiredEmail = Required<Pick<User, 'email'>> & Partial<Omit<User, 'email'>>;

type MyPick<T, K extends keyof T> = {
  [P in K]: T[P];
};

type MyOmit<T, K extends keyof T> = MyPick<T, Exclude<keyof T, K>>;

type Test = MyPick<User, 'id' | 'email'>;

interface Profile { user: User; meta: { version: number } }

type BadPatch = Partial<Profile>;
// patch.user is User | undefined — not Partial<User>

type DeepPartial<T> = { [K in keyof T]?: T[K] extends object ? DeepPartial<T[K]> : T[K] };
// custom deep partial for nested PATCH
